-- 1023: Injection molding visual inspection and weight check calculators.
--
-- GENERATED by scripts/generate-plastic-molding-calculators-migration.ts from
-- src/modules/bom-items/costing/plastic-molding/calculators/plastic-molding-calculators.json.
-- Do not edit by hand: change the spec and regenerate.
--
-- ROOT CAUSE
--
-- Visual inspection is routed for every molded part, but it was reported as having no sourced data. An audit of memory/ found it staged under
-- Secondary process (2026-Secondary): visualInspectTimeStandard, 5 min per square metre of part surface, and defaultPercentToBeTested, 100 %.
-- This calculator times the inspection as the surface area x that rate x the share inspected, per part (formula registry F-34). A helper: the
-- injection engine runs it for the routed visual inspection and charges it at the bench rate. The weight check calculator times one check of 10 s
-- every 1,000 parts by the press operator (the costing engineer's defaults) and derives the bench scale's hourly rate from its price (OHAUS
-- Defender 3000) with the machine-hour rate pattern of migration 580 (formula registry F-35).
--
-- This migration creates one global calculator per spec entry (inputs are the
-- values the cost engine seeds, each shown with its source in the calculation
-- trace; calculated fields are the formulas the engine evaluates, it holds
-- none) and links every Plastic Molding catalog operation it computes to its
-- calculator in process_calculator_mappings.
--
-- Requires migration 804 (calculators.retired_at).
-- Self-contained, idempotent, post-checked.

BEGIN;

-- Injection Molding - Visual Inspection
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Injection Molding - Visual Inspection$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Injection Molding - Visual Inspection$q$, 'process', 'single', false, true, true, $q$The visual inspection of a molded part, per part (formula registry F-34): the part surface area at memory/Secondary process visualInspectTimeStandard (min per square metre), for the share of parts inspected (defaultPercentToBeTested). A helper: the injection engine runs it for the routed visual inspection and charges it at the bench rate.$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$The visual inspection of a molded part, per part (formula registry F-34): the part surface area at memory/Secondary process visualInspectTimeStandard (min per square metre), for the share of parts inspected (defaultPercentToBeTested). A helper: the injection engine runs it for the routed visual inspection and charges it at the bench rate.$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Part Surface Area$q$, $q$Part Surface Area (mm²)$q$, $q$number$q$, $q$mm²$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Visual Inspection Rate$q$, $q$Visual Inspection Rate (min/m²)$q$, $q$number$q$, $q$min/m²$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Percent Inspected$q$, $q$Percent Inspected (%)$q$, $q$number$q$, $q$%$q$, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q$floor({Part Surface Area} / 1000000 * {Visual Inspection Rate} * 60 * {Percent Inspected} / 100 * 100 + 0.5) / 100$q$, 4, false);
END
$calc$;

-- Injection Molding - Weight Check
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Injection Molding - Weight Check$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Injection Molding - Weight Check$q$, 'process', 'single', false, true, true, $q$The periodic weight check of molded parts, per part (formula registry F-35): one check of Time Per Check every Sampling Interval parts, by the press operator on a bench scale (reference/quality-inspection-reference.csv: the costing engineer's defaults, engineering estimates). The scale's hourly rate is the machine-hour rate pattern of migration 580: (price x (1 - salvage) / life + price x maintenance + price x installation / life) / (scheduled hours x uptime x utilization), with the press economics of memory/Plastic Modeling (reference/equipment-economics-reference.csv). A helper: the injection engine charges the time at the operator rate plus the scale rate.$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$The periodic weight check of molded parts, per part (formula registry F-35): one check of Time Per Check every Sampling Interval parts, by the press operator on a bench scale (reference/quality-inspection-reference.csv: the costing engineer's defaults, engineering estimates). The scale's hourly rate is the machine-hour rate pattern of migration 580: (price x (1 - salvage) / life + price x maintenance + price x installation / life) / (scheduled hours x uptime x utilization), with the press economics of memory/Plastic Modeling (reference/equipment-economics-reference.csv). A helper: the injection engine charges the time at the operator rate plus the scale rate.$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
