  VALUES
    (v_id, $q$Time Per Check$q$, $q$Time Per Check (s)$q$, $q$number$q$, $q$s$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Sampling Interval$q$, $q$Sampling Interval (parts per check)$q$, $q$number$q$, $q$parts per check$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Scale Price$q$, $q$Scale Price (USD)$q$, $q$number$q$, $q$USD$q$, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Equipment Life$q$, $q$Equipment Life (yr)$q$, $q$number$q$, $q$yr$q$, NULL, NULL, NULL, NULL, 4, true),
    (v_id, $q$Salvage Factor$q$, $q$Salvage Factor (%)$q$, $q$number$q$, $q$%$q$, NULL, NULL, NULL, NULL, 5, true),
    (v_id, $q$Maintenance Factor$q$, $q$Maintenance Factor (%/yr)$q$, $q$number$q$, $q$%/yr$q$, NULL, NULL, NULL, NULL, 6, true),
    (v_id, $q$Installation Factor$q$, $q$Installation Factor (%)$q$, $q$number$q$, $q$%$q$, NULL, NULL, NULL, NULL, 7, true),
    (v_id, $q$Scheduled Hours$q$, $q$Scheduled Hours (h/yr)$q$, $q$number$q$, $q$h/yr$q$, NULL, NULL, NULL, NULL, 8, true),
    (v_id, $q$Uptime$q$, $q$Uptime (%)$q$, $q$number$q$, $q$%$q$, NULL, NULL, NULL, NULL, 9, true),
    (v_id, $q$Utilization$q$, $q$Utilization$q$, $q$number$q$, $q$$q$, NULL, NULL, NULL, NULL, 10, true),
    (v_id, $q$Scale Rate$q$, $q$Scale Rate (USD/h)$q$, $q$calculated$q$, $q$USD/h$q$, NULL, NULL, NULL, $q$({Scale Price} * (1 - {Salvage Factor} / 100) / {Equipment Life} + {Scale Price} * {Maintenance Factor} / 100 + {Scale Price} * {Installation Factor} / 100 / {Equipment Life}) / ({Scheduled Hours} * {Uptime} / 100 * {Utilization})$q$, 11, false),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Time Per Check} / {Sampling Interval}$q$, 12, false);
END
